14	// TestSaveAndQueryTransaction 测试分表保存和查询
15	func TestSaveAndQueryTransaction(t *testing.T) {
16		cleanup := initTestEnv(t)
17		defer cleanup()
18	
19		// 保存记录
20		requestBody := base64.StdEncoding.EncodeToString([]byte(`{"model":"claude-3","tools":[{"name":"Bash"},{"name":"Read"}]}`))
21		srcRequestBody := base64.StdEncoding.EncodeToString([]byte(`{"model":"gpt-4o","tools":[{"type":"function","function":{"name":"source_only_tool"}}]}`))
22		err := SaveAgentHttpTransaction(
23			"testuser", "model-a",
24			1,
25			"sk-test-key-123", 42,
26			0, // 验证 SaveAgentHttpTransaction 对空算法类型默认落库为协议直连
27			"dst-model-a",
28			AgentProtocolType_Anthropic,
29			"POST", "https://api.test.com/v1/messages", "127.0.0.1:12345",
30			100,
31			"Content-Type: application/json\nAuthorization: Bearer raw-forwarded-key", "User-Agent: TestTool/1.0\nAuthorization: Bearer raw-client-key", requestBody, srcRequestBody,
32			"200 OK", 200,
33			"Content-Type: application/json", "Content-Type: application/json", `{"ok":true}`, "",
34			time.Now(), time.Now(), time.Now(), time.Now(),
35			150,
36			"TestTool/1.0",
37			"",                   // agentToolName
38			"",                   // agentToolInfo
39			"unknown_session_id", // 测试使用占位 session_id
40			cfg.DBMysqlSubTableNumber,
41			0, 0, 0,
42		)
43		if err != nil {
44			t.Fatalf("save transaction failed: %v", err)
45		}
46	
47		// 查询记录
48		records, total, err := QueryAgentHttpTransactions("testuser", "model-a", cfg.DBMysqlSubTableNumber, 1, 10, "", "", "", false, 0, "", "", "", 3, 0, 0)
49		if err != nil {
50			t.Fatalf("query transaction failed: %v", err)
51		}
52		if total != 1 {
53			t.Errorf("total = %d, want 1", total)
54		}
55		if len(records) != 1 {
56			t.Fatalf("records len = %d, want 1", len(records))
57		}
58	
59		r := records[0]
60		if r.UserName != "testuser" {
61			t.Errorf("user_name = %s, want testuser", r.UserName)
62		}
63		if r.RequestMethod != "POST" {
64			t.Errorf("method = %s, want POST", r.RequestMethod)
65		}
66		if r.ElapsedMs != 150 {
67			t.Errorf("elapsed_ms = %d, want 150", r.ElapsedMs)
68		}
69		if r.RequestTools != "Bash,Read" {
70			t.Errorf("request_tools = %q, want %q", r.RequestTools, "Bash,Read")
71		}
72		if r.DstEndPointAlgorithmType != DstEndPointAlgorithmType_Direct {
73			t.Errorf("dst_endpoint_algorithm_type = %d, want %d", r.DstEndPointAlgorithmType, DstEndPointAlgorithmType_Direct)
74		}
75		if r.SessionID != "unknown_session_id" {
76			t.Errorf("session_id = %q, want %q", r.SessionID, "unknown_session_id")
77		}
78	
79		var rawHeaders struct {
80			RequestHeaders            string `gorm:"column:request_headers"`
81			RequestSrcProtocolHeaders string `gorm:"column:request_src_protocol_headers"`
82		}
83		tableName := GetAgentHttpTableName("testuser", "model-a", cfg.DBMysqlSubTableNumber)
84		if err := DB.Table(tableName).Select("request_headers, request_src_protocol_headers").Where("id = ?", r.ID).First(&rawHeaders).Error; err != nil {
85			t.Fatalf("query raw headers failed: %v", err)
86		}
87		if !strings.Contains(rawHeaders.RequestHeaders, "raw-forwarded-key") {
88			t.Fatalf("raw request_headers should keep forwarded key, got %q", rawHeaders.RequestHeaders)
89		}
90		if !strings.Contains(rawHeaders.RequestSrcProtocolHeaders, "raw-client-key") {
91			t.Fatalf("raw request_src_protocol_headers should keep client key, got %q", rawHeaders.RequestSrcProtocolHeaders)
92		}
93		if strings.Contains(rawHeaders.RequestHeaders, authorizationBearerAPIKeyMask) || strings.Contains(rawHeaders.RequestSrcProtocolHeaders, authorizationBearerAPIKeyMask) {
94			t.Fatalf("raw database headers should not be masked: %#v", rawHeaders)
95		}
96	
97		reqHeaders, _, _, _, err := GetAgentHttpTransactionDetailByID("testuser", "model-a", cfg.DBMysqlSubTableNumber, r.ID)
98		if err != nil {
99			t.Fatalf("get detail by id failed: %v", err)
100		}
101		if strings.Contains(reqHeaders, "raw-forwarded-key") || !strings.Contains(reqHeaders, "Authorization: Bearer "+authorizationBearerAPIKeyMask) {
102			t.Fatalf("request_headers detail should be masked, got %q", reqHeaders)
103		}
104	
105		// 按 ID 查询
106		found, err := GetAgentHttpTransactionByID("testuser", "model-a", cfg.DBMysqlSubTableNumber, r.ID)
107		if err != nil {
108			t.Fatalf("get by id failed: %v", err)
109		}
110		if found.ID != r.ID {
111			t.Errorf("id mismatch: %d vs %d", found.ID, r.ID)
112		}
113		if found.RequestTools != "Bash,Read" {
114			t.Errorf("detail request_tools = %q, want %q", found.RequestTools, "Bash,Read")
115		}
116		if found.RequestTools == "source_only_tool" {
117			t.Errorf("request_tools should be parsed from forwarded body, not srcBody")
118		}
119		if strings.Contains(found.RequestHeaders, "raw-forwarded-key") || !strings.Contains(found.RequestHeaders, "Authorization: Bearer "+authorizationBearerAPIKeyMask) {
120			t.Fatalf("found request_headers should be masked, got %q", found.RequestHeaders)
121		}
122		if strings.Contains(found.RequestSrcProtocolHeaders, "raw-client-key") || !strings.Contains(found.RequestSrcProtocolHeaders, "Authorization: Bearer "+authorizationBearerAPIKeyMask) {
123			t.Fatalf("found request_src_protocol_headers should be masked, got %q", found.RequestSrcProtocolHeaders)
124		}
125	
126		// 计数
127		count, err := CountAgentHttpTransactions("testuser", "model-a", 0, cfg.DBMysqlSubTableNumber)
128		if err != nil {
129			t.Fatalf("count failed: %v", err)
130		}
131		if count != 1 {
132			t.Errorf("count = %d, want 1", count)
133		}
134	}
