136	// TestSaveTransactionWithInvalidUTF8ResponseBody 回归测试：修复 /ChatAnalysis
137	// 上 MiniMax 等源站的记录丢失 bug。response_body 中混有非 UTF-8 字节时，
138	// SaveAgentHttpTransaction 必须成功（不抛 Error 1366），且记录必须能从
139	// 哈希分表中按 user+model 查询到 —— 否则 /ChatAnalysis 页看不到这条记录。
140	func TestSaveTransactionWithInvalidUTF8ResponseBody(t *testing.T) {
141		cleanup := initTestEnv(t)
142		defer cleanup()
143	
144		// 构造一个带非 UTF-8 字节的响应体，模拟 MiniMax thinking 块里的二进制签名。
145		// 这正是真实生产环境中触发 MySQL Error 1366 的输入。
146		respBodyWithBinary := "{\"thinking\":\"hello\x85=\x01\x00\xC4j\xAA\xF54\x95world\"}"
147	
148		err := SaveAgentHttpTransaction(
149			"utf8user", "test-model-bad",
150			1, "sk-test-utf8", 7,
151			DstEndPointAlgorithmType_Direct,
152			"MiniMax-M3",
153			AgentProtocolType_Anthropic,
154			"POST", "https://api.minimaxi.com/anthropic", "127.0.0.1:1",
155			100,
156			"Content-Type: application/json", "Content-Type: application/json", base64.StdEncoding.EncodeToString([]byte(`{"model":"x"}`)), "",
157			"200 OK", 200,
158			"Content-Type: application/json", "Content-Type: application/json", respBodyWithBinary, "",
159			time.Now(), time.Now(), time.Now(), time.Now(),
160			42, "TestTool/1.0",
161			"",                   // agentToolName
162			"",                   // agentToolInfo
163			"unknown_session_id", // 测试使用占位 session_id
164			cfg.DBMysqlSubTableNumber,
165			10, 20, 30,
166		)
167		if err != nil {
168			t.Fatalf("save with non-UTF8 response body failed (regression of /ChatAnalysis missing-record bug): %v", err)
169		}
170	
171		// 记录必须能从分表查回来
172		records, total, err := QueryAgentHttpTransactions(
173			"utf8user", "test-model-bad", cfg.DBMysqlSubTableNumber, 1, 10, "", "", "", false, 0, "", "", "", 3, 0, 0,
174		)
175		if err != nil {
176			t.Fatalf("query failed: %v", err)
177		}
178		if total != 1 {
179			t.Fatalf("total = %d, want 1 (record was lost on save)", total)
180		}
181		if len(records) != 1 {
182			t.Fatalf("records len = %d, want 1", len(records))
183		}
184	
185		// 列表查询的 Select 不包含大字段（与生产行为一致），改用 GetAgentHttpTransactionByID 取回完整行
186		full, err := GetAgentHttpTransactionByID("utf8user", "test-model-bad", cfg.DBMysqlSubTableNumber, records[0].ID)
187		if err != nil {
188			t.Fatalf("get by id failed: %v", err)
189		}
190	
191		// response_body 在数据库中应已 base64 编码，前端 decodeBody() 用 atob 解码
192		decoded, err := base64.StdEncoding.DecodeString(full.ResponseBody)
193		if err != nil {
194			t.Fatalf("response_body should be base64-encodable, got err: %v", err)
195		}
196		if !strings.Contains(string(decoded), "world") {
197			t.Errorf("decoded body missing tail content: %q", string(decoded))
198		}
199	}
