201	// TestSanitizeUTF8 单元测试：sanitizeUTF8 把非 UTF-8 字节替换为 U+FFFD。
202	func TestSanitizeUTF8(t *testing.T) {
203		cases := []struct {
204			name  string
205			input string
206			want  string
207		}{
208			{"valid utf-8 passthrough", "hello 世界", "hello 世界"},
209			{"lone 0x85 becomes FFFD", "a\x85b", "a�b"},
210			{"empty string", "", ""},
211			{"all ascii passthrough", "plain ascii", "plain ascii"},
212		}
213		for _, c := range cases {
214			t.Run(c.name, func(t *testing.T) {
215				got := sanitizeUTF8(c.input)
216				if got != c.want {
217					t.Errorf("sanitizeUTF8(%q) = %q, want %q", c.input, got, c.want)
218				}
219			})
220		}
221	}
