1336	// clampStatsDays 把 days 限制到合法范围（0=无限制；>0 限制到 365）
1337	func clampStatsDays(days int) int {
1338		if days < 0 {
1339			return 0
1340		}
1341		if days > 365 {
1342			return 365
1343		}
1344		return days
1345	}
1346	
1347	// v2.0.40：时间跨度统一编码为单个 int（span）。
1348	//   - span == 0：无限制（不加时间过滤）
1349	//   - span  > 0：最近 span 天（上限 365）
1350	//   - span  < 0：最近 (-span) 小时（上限 -720，即 30 天等价小时数）
1351	//
1352	// 之所以用「负值编码小时」而不是新增字段，是为了让 /AIRouteManage 列表列既有的
1353	// 单一 days 参数在两个 API（manager/user）与两个 DB 查询函数间零签名改动地贯通，
1354	// 同时保证 makeStatsCacheKey 对小时/天产生互不冲突的缓存键。
1355	const maxStatsSpanHours = 720 // 30 天等价小时数，防止小时值撑爆 created_at 过滤
1356	
1357	// resolveStatsSpanCutoff 解释 span，返回 (cutoff, 是否需要过滤)。
1358	// 需要过滤时表示只统计 created_at >= cutoff 的记录。
1359	func resolveStatsSpanCutoff(span int) (time.Time, bool) {
1360		if span == 0 {
1361			return time.Time{}, false
1362		}
1363		if span > 0 {
1364			days := clampStatsDays(span)
1365			if days <= 0 {
1366				return time.Time{}, false
1367			}
1368			return time.Now().AddDate(0, 0, -days), true
1369		}
1370		hours := -span
1371		if hours > maxStatsSpanHours {
1372			hours = maxStatsSpanHours
1373		}
1374		return time.Now().Add(-time.Duration(hours) * time.Hour), true
1375	}
1376	
1377	// widerStatsSpan 在两个 span 中返回覆盖时间窗口更宽的那个（供批量聚合取最宽窗口）。
1378	// 0（无限制）覆盖一切，其次是天（正值），最后是小时（负值）。天/小时通过换算成小时数比较。
1379	func widerStatsSpan(a, b int) int {
1380		if a == 0 || b == 0 {
1381			return 0
1382		}
1383		spanHours := func(s int) int {
1384			if s > 0 {
1385				return clampStatsDays(s) * 24
1386			}
1387			h := -s
1388			if h > maxStatsSpanHours {
1389				h = maxStatsSpanHours
1390			}
1391			return h
1392		}
1393		if spanHours(a) >= spanHours(b) {
1394			return a
1395		}
1396		return b
1397	}
