1399	// applyStatsDaysWhere 给 GORM chain 加 created_at 时间过滤；days<=0 不加。
1400	// 用 Go 端预先计算的 cutoff timestamp，避免 SQL 方言差异（MySQL DATE_SUB / SQLite julianday）。
1401	func applyStatsDaysWhere(tx *gorm.DB, days int) *gorm.DB {
1402		if days > 0 {
1403			return tx.Where("created_at >= ?", time.Now().AddDate(0, 0, -days))
1404		}
1405		return tx
1406	}
