1409	// 聚合范围为全站所有分表，不按模型/用户/Agent 维度拆分。
1410	type DailyStat struct {
1411		Date         string `json:"date"`
1412		Count        int64  `json:"count"`
1413		TokensInput  uint64 `json:"tokens_input"`
1414		TokensOutput uint64 `json:"tokens_output"`
1415		TokensTotal  uint64 `json:"tokens_total"`
1416	}
