1418	// GetDailyStatsAll 全站维度按天聚合调用次数与 Tokens，用于时序折线图。
1419	// days<=0 表示无限制；days>0 仅统计 created_at 在最近 N 天内的记录（最大 365）。
1420	// 使用 Go 端按 created_at 日期分组，避免 SQL 方言差异（MySQL DATE_FORMAT / SQLite strftime），
1421	// 与 GetModelInfoUsageStatsAll 一致的全表扫描 + Go 聚合模式。
1422	func GetDailyStatsAll(subTableNum int, days int) ([]DailyStat, error) {
1423		if DB == nil {
1424			return nil, fmt.Errorf("database not initialized")
1425		}
1426		subTableNum = normalizeSubTableNum(subTableNum)
1427		days = clampStatsDays(days)
1428	
1429		type rowData struct {
1430			CreatedAt        time.Time
1431			TokensInputSize  uint64
1432			TokensOutputSize uint64
1433			TokensAllSize    uint64
1434		}
1435	
1436		acc := make(map[string]*DailyStat)
1437		for i := 0; i < subTableNum; i++ {
1438			tableName := fmt.Sprintf("TAgentHttpTransactionDataItem_%02d", i)
1439			if !IsTableExists(tableName) {
1440				continue
1441			}
1442	
1443			var rows []rowData
1444			err := applyStatsDaysWhere(DB.Table(tableName), days).
1445				Select("created_at, COALESCE(tokens_input_size, 0) as tokens_input_size, COALESCE(tokens_output_size, 0) as tokens_output_size, COALESCE(tokens_all_size, 0) as tokens_all_size").
1446				Scan(&rows).Error
1447			if err != nil {
1448				return nil, fmt.Errorf("failed to get daily stats from %s: %w", tableName, err)
1449			}
1450	
1451			for _, row := range rows {
1452				dateKey := row.CreatedAt.Format("2006-01-02")
1453				if existing, ok := acc[dateKey]; ok {
1454					existing.Count++
1455					existing.TokensInput += row.TokensInputSize
1456					existing.TokensOutput += row.TokensOutputSize
1457					existing.TokensTotal += row.TokensAllSize
1458				} else {
1459					acc[dateKey] = &DailyStat{
1460						Date:         dateKey,
1461						Count:        1,
1462						TokensInput:  row.TokensInputSize,
1463						TokensOutput: row.TokensOutputSize,
1464						TokensTotal:  row.TokensAllSize,
1465					}
1466				}
1467			}
1468		}
1469	
1470		if len(acc) == 0 {
1471			return []DailyStat{}, nil
1472		}
1473	
1474		results := make([]DailyStat, 0, len(acc))
1475		if days > 0 {
1476			now := time.Now()
1477			for i := days - 1; i >= 0; i-- {
1478				date := now.AddDate(0, 0, -i).Format("2006-01-02")
1479				if stat, ok := acc[date]; ok {
1480					results = append(results, *stat)
1481				} else {
1482					results = append(results, DailyStat{Date: date})
1483				}
1484			}
1485		} else {
1486			for _, stat := range acc {
1487				results = append(results, *stat)
1488			}
1489			sort.Slice(results, func(i, j int) bool { return results[i].Date < results[j].Date })
1490		}
1491	
1492		return results, nil
1493	}
