1769	// ============================================================================
1770	// v2.0.29: 浏览记录批量删除（仅管理员端）
1771	// ============================================================================
1772	
1773	// maxBatchDeleteIDs 单次批量删除 ID 上限
1774	//
1775	// 防止 WHERE id IN (...) 子句超长撞 max_allowed_packet（MySQL 默认 64MB / 单 SQL
1776	// 限制）。本项目浏览记录 ID 为 uint64，按 20 字符 + 1 分隔符估，500 条 ~10KB，
1777	// 远低于 64MB，但留足冗余避免极端情况。
1778	const maxBatchDeleteIDs = 500
1779	
1780	// DeleteAgentHttpTransaction 单条硬删除（管理员端 v2.0.29）
1781	//
1782	// 使用 Unscoped() 硬删除：TAgentHttpTransactionDataItem 模型虽然声明了
1783	// gorm.DeletedAt 字段，但整个项目从未写过它（架构上把浏览记录视为流水），
1784	// 软删反而会留下大量 dead rows 拖累后续查询。管理员清理历史异常记录时硬删更干净。
1785	//
1786	// 删除后立即调用 invalidateStatsCacheByUserModel 失效该 user+model 的统计缓存，
1787	// 避免 /ChatAnalysisTotal 等统计页继续显示陈旧 count。
1788	func DeleteAgentHttpTransaction(userName, modelName string, subTableNum int, id uint64) (int64, error) {
1789		if id == 0 {
1790			return 0, fmt.Errorf("invalid id: 0")
1791		}
1792		if userName == "" || modelName == "" {
1793			return 0, fmt.Errorf("invalid params: user_name and model_name are required")
1794		}
1795		if DB == nil {
1796			return 0, fmt.Errorf("database not initialized")
1797		}
1798		if subTableNum <= 0 {
1799			subTableNum = DEFAULT_SUB_TABLE_NUM
1800		}
1801	
1802		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
1803		result := DB.Table(tableName).Unscoped().
1804			Where("id = ? AND user_name = ? AND model_name = ?", id, userName, modelName).
1805			Delete(&TAgentHttpTransactionDataItem{})
1806		if result.Error != nil {
1807			return 0, fmt.Errorf("failed to delete record (id=%d): %w", id, result.Error)
1808		}
1809	
1810		// 删除后立即失效该 user+model 的统计缓存，避免 /ChatAnalysisTotal 等页面
1811		// 继续显示陈旧 count。
1812		invalidateStatsCacheByUserModel(userName, modelName)
1813	
1814		return result.RowsAffected, nil
1815	}
1816	
1817	// DeleteAgentHttpTransactions 批量硬删除（管理员端 v2.0.29）
1818	//
1819	// 单条 SQL `WHERE id IN ? AND user_name = ? AND model_name = ?` + Unscoped()，
1820	// 不循环调用单条删除（v2.0.24 SpiderDailyInfo 的循环删除是 N+1 必要妥协，
1821	// 本场景管理员跳过权限预检、无 N+1 风险）。
1822	//
1823	// 返回 RowsAffected：被实际删除的行数。管理员端无权限概念，仅区分"已删除"与"不存在"
1824	// 两桶：skippedNotFound = len(req.IDs) - deleted。
1825	//
1826	// 检查顺序：参数校验（含 len(ids) 与 maxBatchDeleteIDs 上限）先于 DB 访问，
1827	// 这样在无 DB 环境下也能精准测试参数校验路径。
1828	func DeleteAgentHttpTransactions(userName, modelName string, subTableNum int, ids []uint64) (int64, error) {
1829		if userName == "" || modelName == "" {
1830			return 0, fmt.Errorf("invalid params: user_name and model_name are required")
1831		}
1832		if len(ids) == 0 {
1833			return 0, nil
1834		}
1835		if len(ids) > maxBatchDeleteIDs {
1836			return 0, fmt.Errorf("too many ids: %d (max %d)", len(ids), maxBatchDeleteIDs)
1837		}
1838		if DB == nil {
1839			return 0, fmt.Errorf("database not initialized")
1840		}
1841		if subTableNum <= 0 {
1842			subTableNum = DEFAULT_SUB_TABLE_NUM
1843		}
1844	
1845		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
1846		result := DB.Table(tableName).Unscoped().
1847			Where("id IN ? AND user_name = ? AND model_name = ?", ids, userName, modelName).
1848			Delete(&TAgentHttpTransactionDataItem{})
1849		if result.Error != nil {
1850			return 0, fmt.Errorf("failed to batch delete (count=%d): %w", len(ids), result.Error)
1851		}
1852	
1853		invalidateStatsCacheByUserModel(userName, modelName)
1854	
1855		return result.RowsAffected, nil
1856	}
