1858	// GetRouteLastUsedTime 查询指定 user+model+protocol 在浏览记录分表中最后一次
1859	// 代理请求发生的时间（created_at 最大值）。
1860	//
1861	// 用于 /AIRouteManage 页面「路由配对列表」展示每条路由最后被实际调用的时间。
1862	//
1863	// 性能优化要点：
1864	//  1. 用 user_name+model_name 哈希定位唯一一张分表（GetAgentHttpTableName），
1865	//     单表内执行 SELECT created_at FROM ... WHERE user_name=? AND model_name=?
1866	//     [AND protocol_type=?] ORDER BY id DESC LIMIT 1；
1867	//  2. ORDER BY id DESC 而非 created_at DESC：id 是主键且单调递增，主键倒序
1868	//     LIMIT 1 在 InnoDB 上是直接定位聚簇索引最右叶子节点（无需 filesort，
1869	//     也无需扫 created_at 上的二级索引），单行 O(1) 返回；
1870	//  3. 仅 SELECT created_at 一列，跳过整行反射 / 模型实例化；
1871	//  4. 用原生 DB.Raw + Row().Scan(time.Time) 替代 GORM Find，避免 100+ 字段
1872	//     反射 + 类型绑定 + soft-delete 自动追加等开销；
1873	//  5. 复用 statsCache（5 分钟 TTL）按 (userName, modelName, subTableNum, protocolType)
1874	//     维度做内存缓存，避免每次列表刷新都对同一对 (user, model) 重复扫描。
1875	//     写入新事务时已有 invalidateStatsCacheByUserModel 兜底失效。
1876	//
1877	// protocolType<=0 表示不限协议（与路由列表语义一致：同 (user, model) 可能存在
1878	// Anthropic + OpenAI 两条路由，protocolType=1/2 才会区分）。
1879	func GetRouteLastUsedTime(userName, modelName string, protocolType int, subTableNum int) (time.Time, error) {
1880		if DB == nil {
1881			return time.Time{}, fmt.Errorf("database not initialized")
1882		}
1883		if subTableNum <= 0 {
1884			subTableNum = DEFAULT_SUB_TABLE_NUM
1885		}
1886	
1887		cacheKey := makeStatsCacheKey("GetRouteLastUsedTime", userName, modelName, subTableNum, protocolType, "")
1888		if cached, ok := getStatsFromCache(cacheKey); ok {
1889			if ts, valid := cached.(time.Time); valid {
1890				return ts, nil
1891			}
1892		}
1893	
1894		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
1895		if !isValidTableName(tableName) {
1896			return time.Time{}, fmt.Errorf("invalid table name: %s", tableName)
1897		}
1898	
1899		// 原生 SQL：单列 + 主键倒序 LIMIT 1，最快路径。表名已经 isValidTableName 校验过，
1900		// 直接 Sprintf 拼接到 SQL；user_name / model_name / protocol_type 走参数化占位符。
1901		var ts time.Time
1902		var query string
1903		var args []interface{}
1904		if protocolType > 0 {
1905			query = fmt.Sprintf(
1906				"SELECT created_at FROM %s WHERE user_name = ? AND model_name = ? AND protocol_type = ? ORDER BY id DESC LIMIT 1",
1907				tableName,
1908			)
1909			args = []interface{}{userName, modelName, protocolType}
1910		} else {
1911			query = fmt.Sprintf(
1912				"SELECT created_at FROM %s WHERE user_name = ? AND model_name = ? ORDER BY id DESC LIMIT 1",
1913				tableName,
1914			)
1915			args = []interface{}{userName, modelName}
1916		}
1917	
1918		row := DB.Raw(query, args...).Row()
1919		if err := row.Scan(&ts); err != nil {
1920			if err == gorm.ErrRecordNotFound || err.Error() == "sql: no rows in result set" {
1921				setStatsToCache(cacheKey, ts) // 缓存零值
1922				return ts, nil
1923			}
1924			return time.Time{}, fmt.Errorf("failed to query last used time from %s: %w", tableName, err)
1925		}
1926	
1927		setStatsToCache(cacheKey, ts)
1928		return ts, nil
1929	}
