1931	// ============================================================================
1932	// v2.0.37: 路由管理页面「加载中」卡顿 —— 批量聚合替代 N+1
1933	// ============================================================================
1934	//
1935	// 根因:
1936	//   - /AIRouteManage 页面前端 loadData() 先请求 list 拿到全部路由后，
1937	//     对每条路由逐个发起 count_record XHR（并发 5），200 条路由 → N 次 SQL；
1938	//   - 同时 enrichRoute 内对每条路由逐个调用 GetRouteLastUsedTime，又 N 次 SQL；
1939	//   - 这两个 N+1 叠加就是「一直加载中」的表象（受浏览器连接池 + 后端 goroutine 调度
1940	//     双重限制，实际完成速度远慢于预期，即便单次 SQL 只 SELECT 单列 LIMIT 1）。
1941	//   - 注意：本项目查询浏览记录时从来都不加载 RequestBody / ResponseBody /
1942	//     RequestSrcProtocolBody / ResponseSrcProtocolBody 这些 longtext 海量字段
1943	//     （QueryAgentHttpTransactions 有显式白名单 Select；GetRouteLastUsedTime 只
1944	//     SELECT created_at），所以 IO 压力单位是在「SQL 次数」而不是「单 SQL 数据量」。
1945	//
1946	// 修复:
1947	//   - 后端新增一条"批量聚合"入口：前端一次性 POST 多个 (user_name, model_name,
1948	//     protocol_type, days) 复合 key，后端按子表哈希聚合，把原来的「N 个分表」×
1949	//     「每个分表 1 条聚合 SQL」发送给 MySQL，DB 端只返回 len(分表数) 行结果。
1950	//   - 原来的 count_record / list 单条路径保留，向后兼容。
1951	//
1952	// SQL 注入防护:
1953	//   - 表名走 isValidTableName 校验（正则 ^[A-Za-z0-9_]+$）；
1954	//   - user_name / model_name / protocol_type / days 全部走参数化占位符 (?)，
1955	//     不直接拼到 SQL 字符串。
1956	
1957	const batchRouteStatsKeyPairMax = 2000
1958	
1959	// RouteBatchStatKey 批量统计时客户端传入的一次查询需求标识
1960	type RouteBatchStatKey struct {
1961		UserName     string `json:"user_name"`
1962		ModelName    string `json:"model_name"`
1963		ProtocolType int    `json:"protocol_type"`
1964	}
1965	
1966	// RouteBatchStatItem 批量统计时客户端请求的单条 key
1967	type RouteBatchStatItem struct {
1968		RouteID  uint64            `json:"route_id"`
1969		Protocol int               `json:"protocol_type"`
1970		Days     int               `json:"days"`
1971		Key      RouteBatchStatKey `json:"key"`
1972	}
1973	
1974	// RouteBatchStatResult 批量统计结果（每个 route_id 对应一行）
1975	type RouteBatchStatResult struct {
1976		RouteID   uint64    `json:"route_id"`
1977		LastUsed  time.Time `json:"last_used_at"`
1978		LastUsedI int64     `json:"last_used_unix"` // 0 表示"未使用"
1979		Count     int64     `json:"count"`
1980	}
1981	
1982	// BatchGetRouteStatsByRouteIDs 按 route_id 批量聚合查询每条路由的
1983	//   - 最近一次代理请求时间 (MAX(created_at))
1984	//   - 过去 days 天内的记录总数（days<=0 表全量）。
1985	//
1986	// 聚合粒度按 user_name + model_name 哈希到的子表划分，每个子表仅执行 1 条聚合
1987	// SQL（GROUP BY user_name, model_name），由 DB 端完成聚合；禁止逐条 SELECT。
1988	//
1989	// 入参校验先于 DB 访问（无 DB 环境也能精准测试参数校验路径）。
1990	func BatchGetRouteStatsByRouteIDs(items []RouteBatchStatItem, subTableNum int) (map[uint64]RouteBatchStatResult, error) {
1991		result := make(map[uint64]RouteBatchStatResult, len(items))
1992		if DB == nil || len(items) == 0 {
1993			return result, nil
1994		}
1995		if subTableNum <= 0 {
1996			subTableNum = DEFAULT_SUB_TABLE_NUM
1997		}
1998		if len(items) > batchRouteStatsKeyPairMax {
1999			items = items[:batchRouteStatsKeyPairMax]
2000		}
2001	
2002		// pairKey: 子表名 + (user_name, model_name) 笛卡尔配对 —— 作为 GROUP BY 聚合的输入条件
2003		type pairKey struct {
2004			table string
2005			user  string
2006			model string
2007		}
2008		// 收集需要查询的 (表, user, model) 互不相同的配对（去重后生成 WHERE IN）
2009		pairSeen := map[pairKey]struct{}{}
2010		// 记录每个 pairKey 对应的 route_id 列表 + 最宽时间窗口的 span（v2.0.40：
2011		// span 负值编码小时，widerStatsSpan 负责在天/小时混合时取更宽窗口）。
2012		// spanSet 区分「尚未收到任何 span」与「span 恰为 0（无限制）」——
2013		// 否则 maxSpan 初值 0 会被 widerStatsSpan(0,x) 恒当成无限制，导致过滤永不生效。
2014		type pairAgg struct {
2015			routeIDs []uint64
2016			maxSpan  int
2017			spanSet  bool
2018		}
2019		pairAggMap := map[pairKey]*pairAgg{}
2020	
2021		for _, it := range items {
2022			if it.RouteID == 0 || it.Key.UserName == "" || it.Key.ModelName == "" {
2023				continue
2024			}
2025			tableName := GetAgentHttpTableName(it.Key.UserName, it.Key.ModelName, subTableNum)
2026			if !isValidTableName(tableName) {
2027				continue
2028			}
2029			pk := pairKey{table: tableName, user: it.Key.UserName, model: it.Key.ModelName}
2030			pairSeen[pk] = struct{}{}
2031			pa := pairAggMap[pk]
2032			if pa == nil {
2033				pa = &pairAgg{}
2034				pairAggMap[pk] = pa
2035			}
2036			pa.routeIDs = append(pa.routeIDs, it.RouteID)
2037			if !pa.spanSet {
2038				pa.maxSpan = it.Days
2039				pa.spanSet = true
2040			} else {
2041				pa.maxSpan = widerStatsSpan(pa.maxSpan, it.Days)
2042			}
2043		}
2044	
2045		// 按子表名聚合：每个子表下发 1 条 GROUP BY 聚合
2046		type shardAgg struct {
2047			table string
2048			pairs []pairKey
2049		}
2050		shardMap := map[string]*shardAgg{}
2051		for pk := range pairSeen {
2052			sa := shardMap[pk.table]
2053			if sa == nil {
2054				sa = &shardAgg{table: pk.table}
2055				shardMap[pk.table] = sa
2056			}
2057			sa.pairs = append(sa.pairs, pk)
2058		}
2059	
2060		for _, sa := range shardMap {
2061			// 组 WHERE IN：一张子表内多对 (user_name, model_name)
2062			conds := make([]string, 0, len(sa.pairs))
2063			args := make([]interface{}, 0, 2*len(sa.pairs))
2064			for _, p := range sa.pairs {
2065				conds = append(conds, "(user_name = ? AND model_name = ?)")
2066				args = append(args, p.user, p.model)
2067			}
2068			where := strings.Join(conds, " OR ")
2069	
2070			// 全局最宽时间窗口（v2.0.40：span 负值编码小时，0=无限制）。
2071			// 同样用 maxSpanSet 区分「未设置」与「无限制(0)」。
2072			maxSpan := 0
2073			maxSpanSet := false
2074			for _, p := range sa.pairs {
2075				pa := pairAggMap[p]
2076				if pa == nil || !pa.spanSet {
2077					continue
2078				}
2079				if !maxSpanSet {
2080					maxSpan = pa.maxSpan
2081					maxSpanSet = true
2082				} else {
2083					maxSpan = widerStatsSpan(maxSpan, pa.maxSpan)
2084				}
2085			}
2086	
2087			sqlText := fmt.Sprintf(
2088				"SELECT user_name, model_name, COUNT(*) AS cnt, MAX(created_at) AS last_used FROM %s WHERE %s",
2089				sa.table, where,
2090			)
2091			if cutoff, ok := resolveStatsSpanCutoff(maxSpan); ok {
2092				// 所有子句共享 created_at 下界（>= cutoff）
2093				// 为确保 AND 绑定整批 OR 子句，把 OR 子句用括号包一层
2094				sqlText = fmt.Sprintf(
2095					"SELECT user_name, model_name, COUNT(*) AS cnt, MAX(created_at) AS last_used FROM %s WHERE (%s) AND created_at >= ?",
2096					sa.table, where,
2097				)
2098				args = append(args, cutoff.Format("2006-01-02 15:04:05"))
2099			}
2100			sqlText += " GROUP BY user_name, model_name"
2101	
2102			rows, err := DB.Raw(sqlText, args...).Rows()
2103			if err != nil {
2104				logger.Printf("[AIRouteManage] BatchGetRouteStats shard %s failed: %v", sa.table, err)
2105				continue
2106			}
2107			// 结果 -> pairAggMap[pk]
2108			for rows.Next() {
2109				var (
2110					user, model string
2111					cnt         int64
2112					lastUsed    time.Time
2113				)
2114				if err := rows.Scan(&user, &model, &cnt, &lastUsed); err != nil {
2115					rows.Close()
2116					return result, err
2117				}
2118				pk := pairKey{table: sa.table, user: user, model: model}
2119				pa := pairAggMap[pk]
2120				if pa == nil {
2121					continue
2122				}
2123				for _, rid := range pa.routeIDs {
2124					r := RouteBatchStatResult{
2125						RouteID:  rid,
2126						LastUsed: lastUsed,
2127						Count:    cnt,
2128					}
2129					if !lastUsed.IsZero() {
2130						r.LastUsedI = lastUsed.Unix()
2131					}
2132					result[rid] = r
2133				}
2134			}
2135			rows.Close()
2136		}
2137	
2138		// 没出现在聚合结果中的 (user, model) 返回零值 —— 从未使用过
2139		for _, it := range items {
2140			if _, ok := result[it.RouteID]; !ok {
2141				result[it.RouteID] = RouteBatchStatResult{RouteID: it.RouteID}
2142			}
2143		}
2144		return result, nil
2145	}

