14	const (
15		proxyAuthRateBurst       = 5
16		proxyAuthRatePerSecond   = 1
17		proxyAuthBucketTTL       = 10 * time.Minute
18		proxyAuthCleanupInterval = time.Minute
19	)
20	
21	var (
22		proxyAPIKeyPattern                  = regexp.MustCompile(`^(sk-[A-Za-z0-9_-]{16,}|[A-Fa-f0-9]{16}-[A-Fa-f0-9]{16}-[0-9]{8,}-[0-9]{6,})$`)
23		authorizationBearerHeaderTextRegexp = regexp.MustCompile(`(?im)(^|[\r\n])([ \t]*Authorization[ \t]*:[ \t]*Bearer[ \t]+)([^\s\r\n]+)`)
24		proxyAuthLimiter                    = newProxyAuthFailureLimiter()
25	)
26	
27	const authorizationBearerAPIKeyMask = "************************"
28	
29	type proxyAuthBucket struct {
30		mu      sync.Mutex
31		tokens  float64
32		last    time.Time
33		updated time.Time
34	}
35	
36	type proxyAuthFailureLimiter struct {
37		buckets sync.Map // ip(string) -> *proxyAuthBucket，正常授权请求仅执行一次 Load，无全局锁竞争
38		gcMu    sync.Mutex
39		lastGC  time.Time
40	}
41	
42	func newProxyAuthFailureLimiter() *proxyAuthFailureLimiter {
43		return &proxyAuthFailureLimiter{lastGC: time.Now()}
44	}
45	
46	// allowFailure 记录一次认证失败并判断是否仍允许返回普通 401。
47	// 超过阈值后返回 false，调用方应直接返回 429，避免暴力猜测 API Key 继续消耗资源。
48	func (l *proxyAuthFailureLimiter) allowFailure(ip string, now time.Time) bool {
49		ip = normalizeProxyClientIP(ip)
50		l.cleanup(now)
51	
52		actual, _ := l.buckets.LoadOrStore(ip, &proxyAuthBucket{tokens: proxyAuthRateBurst, last: now, updated: now})
53		bucket := actual.(*proxyAuthBucket)
54	
55		bucket.mu.Lock()
56		defer bucket.mu.Unlock()
57		bucket.refill(now)
58		if bucket.tokens < 1 {
59			return false
60		}
61		bucket.tokens--
62		return true
63	}
64	
65	func (l *proxyAuthFailureLimiter) isLimited(ip string, now time.Time) bool {
66		actual, ok := l.buckets.Load(normalizeProxyClientIP(ip))
67		if !ok {
68			return false
69		}
70	
71		bucket := actual.(*proxyAuthBucket)
72		bucket.mu.Lock()
73		defer bucket.mu.Unlock()
74		bucket.refill(now)
75		return bucket.tokens < 1
76	}
77	
78	func (l *proxyAuthFailureLimiter) reset(ip string) {
79		l.buckets.Delete(normalizeProxyClientIP(ip))
80	}
81	
82	func (l *proxyAuthFailureLimiter) cleanup(now time.Time) {
83		if now.Sub(l.lastGC) < proxyAuthCleanupInterval {
84			return
85		}
86		l.gcMu.Lock()
87		defer l.gcMu.Unlock()
88		if now.Sub(l.lastGC) < proxyAuthCleanupInterval {
89			return
90		}
91		l.buckets.Range(func(key, value any) bool {
92			bucket := value.(*proxyAuthBucket)
93			bucket.mu.Lock()
94			stale := now.Sub(bucket.updated) > proxyAuthBucketTTL
95			bucket.mu.Unlock()
96			if stale {
97				l.buckets.Delete(key)
98			}
99			return true
100		})
101		l.lastGC = now
102	}
103	
104	func (b *proxyAuthBucket) refill(now time.Time) {
105		elapsed := now.Sub(b.last).Seconds()
106		if elapsed > 0 {
107			b.tokens += elapsed * proxyAuthRatePerSecond
108			if b.tokens > proxyAuthRateBurst {
109				b.tokens = proxyAuthRateBurst
110			}
111			b.last = now
112		}
113		b.updated = now
114	}
