123	func getProxyClientIP(r *http.Request) string {
124		host, _, err := net.SplitHostPort(r.RemoteAddr)
125		if err == nil && host != "" {
126			return host
127		}
128		return r.RemoteAddr
129	}
130	
131	func isValidProxyAPIKeyFormat(apiKey string) bool {
132		return proxyAPIKeyPattern.MatchString(apiKey)
133	}
134	
135	func writeProxyAuthFailure(w http.ResponseWriter, r *http.Request, message string) {
136		clientIP := getProxyClientIP(r)
137		if !proxyAuthLimiter.allowFailure(clientIP, time.Now()) {
138			http.Error(w, `{"error":"Too Many Requests","message":"Too many failed authentication attempts"}`, http.StatusTooManyRequests)
139			return
140		}
141		http.Error(w, `{"error":"Unauthorized","message":"`+message+`"}`, http.StatusUnauthorized)
142	}
143	
144	func writeProxyRateLimited(w http.ResponseWriter) {
145		http.Error(w, `{"error":"Too Many Requests","message":"Too many failed authentication attempts"}`, http.StatusTooManyRequests)
146	}
147	
148	func copySafeProxyRequestHeaders(dst http.Header, src http.Header, clientIP string, protocolType int) {
149		for key, values := range src {
150			canonical := http.CanonicalHeaderKey(key)
151			if !shouldForwardProxyHeader(canonical, protocolType) {
152				continue
153			}
154			for _, value := range values {
155				dst.Add(canonical, value)
156			}
157		}
158		if clientIP != "" {
159			dst.Set("X-Forwarded-For", clientIP)
160		}
161	}
162	
163	func shouldForwardProxyHeader(key string, protocolType int) bool {
164		switch strings.ToLower(key) {
165		case "connection", "keep-alive", "proxy-authenticate", "proxy-authorization",
166			"te", "trailer", "transfer-encoding", "upgrade", "host", "cookie",
167			"authorization", "x-api-key", "x-forwarded-for", "x-forwarded-host",
168			"x-forwarded-proto", "x-real-ip", "content-length":
169			return false
170		case "content-type", "accept", "user-agent", "x-request-id",
171			"anthropic-version", "anthropic-beta", "openai-beta":
172			return true
173		}
174		return strings.HasPrefix(strings.ToLower(key), "x-stainless-") || protocolType == AgentProtocolType_OpenAI && strings.HasPrefix(strings.ToLower(key), "openai-")
175	}
176	
177	func redactSensitiveHeaderValue(key, value string) string {
178		switch strings.ToLower(key) {
179		case "authorization":
180			return "Bearer ***"
181		case "x-api-key", "api-key", "proxy-authorization", "cookie", "set-cookie":
182			return "***"
183		}
184		return value
185	}
186	
187	func redactAPIKey(apiKey string) string {
188		if apiKey == "" {
189			return ""
190		}
191		if len(apiKey) <= 8 {
192			return "***"
193		}
194		return apiKey[:4] + "***" + apiKey[len(apiKey)-4:]
195	}
196	
197	func formatRedactedHeaders(headers http.Header) string {
198		var b strings.Builder
199		for key, values := range headers {
200			fmt.Fprintf(&b, "%s: %s\n", key, redactSensitiveHeaderValue(key, strings.Join(values, ", ")))
201		}
202		return b.String()
203	}
204	
205	func formatRawHeaders(headers http.Header) string {
206		var b strings.Builder
207		for key, values := range headers {
208			fmt.Fprintf(&b, "%s: %s\n", key, strings.Join(values, ", "))
209		}
210		return b.String()
211	}
212	
213	func redactAuthorizationBearerHeaderText(headers string) string {
214		if headers == "" {
215			return ""
216		}
217		return authorizationBearerHeaderTextRegexp.ReplaceAllString(headers, "${1}${2}"+authorizationBearerAPIKeyMask)
218	}
