220	type cappedLogWriter struct {
221		buf   []byte
222		limit int
223		total int64
224	}
225	
226	func newCappedLogWriter(limit int) *cappedLogWriter {
227		return &cappedLogWriter{limit: limit, buf: make([]byte, 0, limit)}
228	}
229	
230	func (w *cappedLogWriter) Write(p []byte) (int, error) {
231		w.total += int64(len(p))
232		if len(w.buf) < w.limit {
233			remain := min(w.limit-len(w.buf), len(p))
234			w.buf = append(w.buf, p[:remain]...)
235		}
236		return len(p), nil
237	}
238	
239	func (w *cappedLogWriter) String() string {
240		if w.total > int64(w.limit) {
241			return string(w.buf) + "\n...[truncated]"
242		}
243		return string(w.buf)
244	}
245	
246	func (w *cappedLogWriter) Len() int64 {
247		return w.total
248	}
249	
250	func redactSensitiveJSONBody(body string) string {
251		if body == "" || strings.Contains(body, "[truncated]") {
252			return body
253		}
254		var v any
255		if err := json.Unmarshal([]byte(body), &v); err != nil {
256			return body
257		}
258		if !redactSensitiveJSONValue(v) {
259			return body
260		}

