217	// intToString 避免对 strconv 的额外 import（已经在 v2040 里导入，但此处保持局部最小依赖）
218	func intToString(n int) string {
219		if n == 0 {
220			return "0"
221		}
222		negative := n < 0
223		if negative {
224			n = -n
225		}
226		digits := []byte{}
227		for n > 0 {
228			digits = append([]byte{byte('0' + n%10)}, digits...)
229			n /= 10
230		}
231		if negative {
232			return "-" + string(digits)
233		}
234		return string(digits)
235	}
