102	// TestBatchSpanAccumulation_NoCollapseToUnlimited 是 v2.0.40 修复真实 bug 的回归测试。
103	// 问题：BatchGetRouteStatsByRouteIDs 的 pairAgg.maxSpan 初值为 0，而 widerStatsSpan(0,x) 恒为 0，
104	// 导致所有实际 span（天/小时）都被合并成「无限制(0)」，SELECT 永不加 created_at 过滤，结果不变。
105	// 此处直接模拟原来的累加循环，验证修复后不再误折叠为 0。
106	func TestBatchSpanAccumulation_NoCollapseToUnlimited(t *testing.T) {
107		// 模拟 pairAgg 的 span 累积流程（与 BatchGetRouteStatsByRouteIDs 一致）
108		type pairAgg struct {
109			maxSpan int
110			spanSet bool
111		}
112		accumulate := func(spans ...int) int {
113			pa := &pairAgg{}
114			for _, s := range spans {
115				if !pa.spanSet {
116					pa.maxSpan = s
117					pa.spanSet = true
118				} else {
119					pa.maxSpan = widerStatsSpan(pa.maxSpan, s)
120				}
121			}
122			return pa.maxSpan
123		}
124	
125		cases := []struct {
126			spans []int
127			want  int
128			desc  string
129		}{
130			{[]int{-1}, -1, "单条小时应保留"},
131			{[]int{-1, -12}, -12, "多条小时取更宽"},
132			{[]int{1, 3}, 3, "多条天取更宽"},
133			{[]int{0, -12}, 0, "含0则覆盖为无限制"},
134			{[]int{-12, 0}, 0, "无论顺序，0覆盖为无限制"},
135			{[]int{-1, 1, -12}, 1, "天/小时混合(1天 vs -12 取更宽的1天)"},
136		}
137		for _, c := range cases {
138			got := accumulate(c.spans...)
139			if got != c.want {
140				t.Errorf("%s: accumulate(%v)=%d, want %d", c.desc, c.spans, got, c.want)
141			}
142		}
143	}
