39		}
40	
41		// 强制使用 JWT 中的用户名，忽略请求体中的 user_name
42		req.UserName = claims.UserName
43	
44		if req.ModelName == "" {
45			json.NewEncoder(w).Encode(ChatAnalysisInterfaceResponse{
46				Success: false,
