57			return
58		}
59	
60		page := req.Page
61		if page < 1 {
62			page = 1
63		}
64	
65		pageSize := req.PageSize
66		switch pageSize {
67		case 1, 3, 5, 10, 15, 20, 50, 100:
68			// 合法值
69		default:
70			pageSize = 3
71		}
72		days := normalizeChatAnalysisDays(req.Days)
73	
