86				Message: "查询失败: " + err.Error(),
87			})
88			return
89		}
90	
91		totalPages := int(math.Ceil(float64(total) / float64(pageSize)))
92		if total > 0 && page > totalPages {
93			page = totalPages
94		}
95	
96		result := &AgentHttpQueryResult{
97			Records:     records,
98			TotalCount:  total,
99			TotalPages:  totalPages,
100			CurrentPage: page,
101			PageSize:    pageSize,
102		}
103	
104		json.NewEncoder(w).Encode(ChatAnalysisInterfaceResponse{
105			Success: true,
106			Message: "查询成功",
107			Data:    result,
108		})
